SELECT gen_random_uuid()::text, 'formula', '$P_{dBm} = 10\log\frac{P}{1\ \text{mW}}$', 'Decibel Power Levels (dBm and dBW)', '$\text{dB} = 10\log\frac{P_2}{P_1},\qquad P_{dBm} = 10\log\frac{P}{1\ \text{mW}},\qquad P_{dBW} = P_{dBm} - 30$', '$\text{dBm}$', 'Power relative to 1 mW or 1 W on a log scale: 0 dBm = 1 mW, 30 dBm = 1 W.', '[{"symbol":"$P$","meaning":"power","unit":"$\\text{W}$"},{"symbol":"$P_1, P_2$","meaning":"powers compared","unit":"$\\text{W}$"}]'::jsonb, '+3 dB doubles the power, +10 dB is ten times; dBm + dB = dBm, but dBm + dBm is meaningless.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'signals, spectrum and decibels' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE'
