SELECT gen_random_uuid()::text, 'formula', '$F = \frac{SNR_{in}}{SNR_{out}},\ T_e = (F - 1)T_0$', 'Noise Figure and Noise Temperature', '$F = \frac{SNR_{in}}{SNR_{out}},\quad NF = 10\log F,\quad T_e = (F - 1)T_0,\ T_0 = 290\ \text{K}$', NULL, 'How much a stage worsens the signal-to-noise ratio.', '[{"symbol":"$SNR_{in}, SNR_{out}$","meaning":"signal-to-noise ratios (plain ratios)","unit":null},{"symbol":"$T_e$","meaning":"equivalent noise temperature","unit":"$\\text{K}$"}]'::jsonb, 'A noiseless stage has F = 1 (0 dB). Use plain ratios in T_e = (F − 1)T₀, not dB.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'noise' AND s."active"), NULL, true, 'PENDING', now(), now()
