SELECT gen_random_uuid()::text, 'formula', '$F = F_1 + \frac{F_2 - 1}{G_1} + \frac{F_3 - 1}{G_1G_2}$', 'Friis Noise Formula (Cascade)', '$F = F_1 + \frac{F_2 - 1}{G_1} + \frac{F_3 - 1}{G_1G_2} + \cdots,\qquad T_e = T_1 + \frac{T_2}{G_1} + \frac{T_3}{G_1G_2} + \cdots$', NULL, 'The first stage dominates a receiver''s noise if its gain is high.', '[{"symbol":"$F_i$","meaning":"noise factor of stage i (ratio)","unit":null},{"symbol":"$G_i$","meaning":"available gain of stage i (ratio)","unit":null},{"symbol":"$T_i$","meaning":"noise temperature of stage i","unit":"$\\text{K}$"}]'::jsonb, 'Put the low-noise amplifier first; a lossy cable before it has F equal to its loss.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'noise' AND s."active"), NULL, true, 'PENDING', now(), now()
