SELECT gen_random_uuid()::text, 'formula', '$\text{saving} = 1 - \frac{m^2/4}{1 + m^2/2}$', 'SSB and DSB-SC Power Saving', '$P_{SSB} = \frac{P_cm^2}{4},\qquad \text{saving}_{SSB} = 1 - \frac{m^2/4}{1 + m^2/2},\qquad \text{saving}_{DSB\text{-}SC} = \frac{1}{1 + m^2/2}$', NULL, 'Suppress the carrier and one sideband: the same message for a fraction of the power and half the bandwidth.', '[{"symbol":"$P_c$","meaning":"carrier power of the equivalent AM","unit":"$\\text{W}$"},{"symbol":"$m$","meaning":"modulation index (0 to 1)","unit":null}]'::jsonb, 'At m = 1: SSB saves 83.3%, DSB-SC 66.7%.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'single sideband' AND s."active"), NULL, true, 'PENDING', now(), now()
