SELECT gen_random_uuid()::text, 'formula', '$Z_0 = \frac{138}{\sqrt{\varepsilon_r}}\log\frac{D}{d}$', 'Characteristic Impedance of Coax and Twin-Lead', '$Z_{0,coax} = \frac{138}{\sqrt{\varepsilon_r}}\log\frac{D}{d},\qquad Z_{0,twin} = \frac{276}{\sqrt{\varepsilon_r}}\log\frac{2s}{d}$', '$\Omega$', 'Line impedance from geometry: Z₀ = √(L/C) per unit length.', '[{"symbol":"$D, d$","meaning":"coax shield inner diameter and centre-conductor diameter","unit":"$\\text{m}$"},{"symbol":"$s$","meaning":"twin-lead spacing (centre to centre)","unit":"$\\text{m}$"},{"symbol":"$\\varepsilon_r$","meaning":"dielectric constant","unit":null}]'::jsonb, 'Common values: 50 Ω and 75 Ω coax, 300 Ω twin-lead.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'transmission lines' AND s."active"), NULL, false, 'PENDING', now(), now()
