SELECT gen_random_uuid()::text, 'formula', '$VF = \frac{1}{\sqrt{\varepsilon_r}}$', 'Velocity Factor', '$VF = \frac{v}{c} = \frac{1}{\sqrt{\varepsilon_r}},\qquad \lambda_{line} = \frac{VF\cdot c}{f}$', NULL, 'Waves travel slower in a cable than in air, so its wavelength is shorter.', '[{"symbol":"$\\varepsilon_r$","meaning":"dielectric constant of the insulation","unit":null},{"symbol":"$f$","meaning":"frequency","unit":"$\\text{Hz}$"}]'::jsonb, 'Cut quarter-wave stubs to VF × λ/4: solid polyethylene coax has VF ≈ 0.66.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'transmission lines' AND s."active"), NULL, true, 'PENDING', now(), now()
