SELECT gen_random_uuid()::text, 'formula', '$Z_{in} = Z_0\frac{Z_L + jZ_0t}{Z_0 + jZ_Lt}$', 'Input Impedance of a Lossless Line', '$Z_{in} = Z_0\,\frac{Z_L + jZ_0\tan\beta\ell}{Z_0 + jZ_L\tan\beta\ell},\qquad \beta = \frac{2\pi}{\lambda}$', '$\Omega$', 'What a load looks like through a length of line.', '[{"symbol":"$t$","meaning":"tan βℓ","unit":null},{"symbol":"$Z_0$","meaning":"characteristic impedance","unit":"$\\Omega$"},{"symbol":"$Z_L$","meaning":"load impedance","unit":"$\\Omega$"},{"symbol":"$\\ell$","meaning":"line length","unit":"$\\text{m}$"},{"symbol":"$\\lambda$","meaning":"wavelength","unit":"$\\text{m}$"}]'::jsonb, 'Shorted stub: jZ₀ tan βℓ; open stub: −jZ₀ cot βℓ. Every λ/2 repeats the load.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'transmission lines' AND s."active"), NULL, false, 'PENDING', now(), now()
