SELECT gen_random_uuid()::text, 'formula', '$L \approx \frac{143}{f_{MHz}}$ m, $R_r = 73\ \Omega$', 'Half-Wave Dipole', '$L \approx 0.95\frac{\lambda}{2} = \frac{142.5}{f(\text{MHz})}\ \text{m},\qquad R_r \approx 73\ \Omega,\qquad D = 1.64\ (2.15\ \text{dBi})$', '$\text{m}$', 'The basic resonant antenna, cut a little short of λ/2 for end effects.', '[{"symbol":"$f$","meaning":"frequency","unit":"$\\text{MHz}$"},{"symbol":"$R_r$","meaning":"radiation resistance","unit":"$\\Omega$"}]'::jsonb, 'A quarter-wave monopole over ground has half the resistance: 36.5 Ω.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'antennas' AND s."active"), NULL, false, 'PENDING', now(), now()
