SELECT gen_random_uuid()::text, 'formula', '$R_r = 80\pi^2\left(\frac{\ell}{\lambda}\right)^2$', 'Radiation Resistance of a Short Dipole', '$R_r = 80\pi^2\left(\frac{\ell}{\lambda}\right)^2 \approx 790\left(\frac{\ell}{\lambda}\right)^2\quad (\text{uniform current})$', '$\Omega$', 'The resistance that accounts for the power a short antenna radiates.', '[{"symbol":"$\\ell$","meaning":"dipole length (≪ λ)","unit":"$\\text{m}$"},{"symbol":"$\\lambda$","meaning":"wavelength","unit":"$\\text{m}$"}]'::jsonb, 'With the usual triangular current it is a quarter of this: 20π²(ℓ/λ)². Short antennas radiate poorly.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'antennas' AND s."active"), NULL, false, 'PENDING', now(), now()
