SELECT gen_random_uuid()::text, 'formula', '$\eta = \frac{R_r}{R_r + R_{loss}},\ G = \eta D$', 'Antenna Efficiency and Gain', '$\eta = \frac{R_r}{R_r + R_{loss}},\qquad G = \eta D,\qquad \text{EIRP} = P_tG_t$', NULL, 'Gain is directivity reduced by the antenna''s own losses.', '[{"symbol":"$R_r, R_{loss}$","meaning":"radiation and loss resistances","unit":"$\\Omega$"},{"symbol":"$D$","meaning":"directivity","unit":null},{"symbol":"$P_t$","meaning":"transmitter power","unit":"$\\text{W}$"}]'::jsonb, 'dBi is relative to isotropic, dBd to a dipole: dBi = dBd + 2.15.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'antennas' AND s."active"), NULL, true, 'PENDING', now(), now()
