SELECT gen_random_uuid()::text, 'formula', '$L = 32.45 + 20\log f_{MHz} + 20\log d_{km}$', 'Free-Space Path Loss', '$L = \left(\frac{4\pi d}{\lambda}\right)^2;\qquad L(\text{dB}) = 32.45 + 20\log f(\text{MHz}) + 20\log d(\text{km})$', '$\text{dB}$', 'The spreading loss between isotropic antennas in free space.', '[{"symbol":"$d$","meaning":"distance","unit":"$\\text{km}$"},{"symbol":"$f$","meaning":"frequency","unit":"$\\text{MHz}$"}]'::jsonb, 'Doubling the distance adds 6 dB; with miles and MHz the constant is 36.6.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'radio wave propagation' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
