SELECT gen_random_uuid()::text, 'formula', '$P_r = P_tG_tG_r\left(\frac{\lambda}{4\pi d}\right)^2$', 'Friis Transmission Equation', '$P_r = P_tG_tG_r\left(\frac{\lambda}{4\pi d}\right)^2;\qquad P_r(\text{dBm}) = P_t + G_t + G_r - L_{fs}$', '$\text{W}$', 'Received power over a line-of-sight free-space link.', '[{"symbol":"$P_t, P_r$","meaning":"transmitted and received power","unit":"$\\text{W}$"},{"symbol":"$G_t, G_r$","meaning":"antenna gains (ratios)","unit":null},{"symbol":"$d$","meaning":"distance","unit":"$\\text{m}$"},{"symbol":"$\\lambda$","meaning":"wavelength","unit":"$\\text{m}$"}]'::jsonb, 'The basis of every link budget: add gains, subtract losses, all in dB.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'radio wave propagation' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE'
