SELECT gen_random_uuid()::text, 'formula', '$d = 4.12(\sqrt{h_t} + \sqrt{h_r})$', 'Radio Horizon', '$d(\text{km}) = 4.12\left(\sqrt{h_t} + \sqrt{h_r}\right),\quad h \text{ in m}\quad (k = 4/3)$', '$\text{km}$', 'Line-of-sight range over a smooth earth, with refraction stretching it to a 4/3 earth radius.', '[{"symbol":"$h_t, h_r$","meaning":"antenna heights","unit":"$\\text{m}$"}]'::jsonb, 'The optical horizon is 3.57√h km; in feet and miles the radio horizon is √(2h).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'radio wave propagation' AND s."active"), NULL, false, 'PENDING', now(), now()
