SELECT gen_random_uuid()::text, 'formula', '$\text{MUF} = \frac{f_c}{\cos\theta},\ f_c = 9\sqrt{N}$', 'Critical Frequency and MUF', '$f_c = 9\sqrt{N_{max}},\qquad \text{MUF} = \frac{f_c}{\cos\theta_i} = f_c\sec\theta_i$', '$\text{Hz}$', 'The highest frequency a layer reflects straight up, and at a slant (the secant law).', '[{"symbol":"$N_{max}$","meaning":"peak electron density","unit":"$\\text{m}^{-3}$"},{"symbol":"$\\theta_i$","meaning":"angle of incidence from the vertical","unit":null}]'::jsonb, 'Sky-wave links work below the MUF; about 85% of it (the FOT) is used for reliability.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'radio wave propagation' AND s."active"), NULL, false, 'PENDING', now(), now()
