SELECT gen_random_uuid()::text, 'formula', '$E = \frac{\sqrt{30P_tG_t}}{d}$', 'Free-Space Field Strength', '$E = \frac{\sqrt{30P_tG_t}}{d}\quad (\text{rms, V/m})$', '$\text{V/m}$', 'Field strength from the power density PG/(4πd²) and free space''s 120π Ω.', '[{"symbol":"$P_t$","meaning":"transmitted power","unit":"$\\text{W}$"},{"symbol":"$G_t$","meaning":"antenna gain (ratio)","unit":null},{"symbol":"$d$","meaning":"distance","unit":"$\\text{m}$"}]'::jsonb, 'Field strength falls as 1/d; power density as 1/d².', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'radio wave propagation' AND s."active"), NULL, false, 'PENDING', now(), now()
