SELECT gen_random_uuid()::text, 'formula', '$NA = \sqrt{n_1^2 - n_2^2} = \sin\theta_a$', 'Numerical Aperture', '$NA = \sin\theta_a = \sqrt{n_1^2 - n_2^2} \approx n_1\sqrt{2\Delta},\qquad \Delta = \frac{n_1 - n_2}{n_1}$', NULL, 'The cone of light a fiber accepts and guides by total internal reflection.', '[{"symbol":"$n_1, n_2$","meaning":"core and cladding refractive indices","unit":null},{"symbol":"$\\theta_a$","meaning":"acceptance half-angle in air","unit":null}]'::jsonb, 'Larger NA collects more light but spreads pulses more (modal dispersion).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'fiber optics' AND s."active"), NULL, true, 'PENDING', now(), now()
