SELECT gen_random_uuid()::text, 'formula', '$V = \frac{2\pi a}{\lambda}NA$', 'V-Number and Modes', '$V = \frac{2\pi a}{\lambda}NA;\qquad V < 2.405 \text{ single-mode};\qquad M \approx \frac{V^2}{2}\ (\text{step index})$', NULL, 'Whether a fiber carries one mode or many at a given wavelength.', '[{"symbol":"$a$","meaning":"core radius","unit":"$\\text{m}$"},{"symbol":"$\\lambda$","meaning":"wavelength","unit":"$\\text{m}$"},{"symbol":"$NA$","meaning":"numerical aperture","unit":null}]'::jsonb, 'Graded-index fiber carries about V²/4 modes.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'fiber optics' AND s."active"), NULL, true, 'PENDING', now(), now()
