SELECT gen_random_uuid()::text, 'formula', '$\Delta t = \frac{Ln_1\Delta}{c}$', 'Modal Dispersion (Step Index)', '$\Delta t = \frac{L\,n_1}{c}\cdot\frac{n_1 - n_2}{n_2} \approx \frac{L\,n_1\Delta}{c},\qquad B \approx \frac{1}{2\Delta t}$', '$\text{s}$', 'The steepest guided ray travels farther than the axial ray, spreading each pulse.', '[{"symbol":"$L$","meaning":"fiber length","unit":"$\\text{m}$"},{"symbol":"$n_1, n_2$","meaning":"core and cladding indices","unit":null},{"symbol":"$\\Delta$","meaning":"relative index difference","unit":null}]'::jsonb, 'Graded-index fiber cuts this by about Δ/8; single-mode removes it.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'fiber optics' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
