SELECT gen_random_uuid()::text, 'formula', '$P_r = P_t - \alpha L - L_c - L_s$', 'Optical Power Budget', '$P_r(\text{dBm}) = P_t(\text{dBm}) - \alpha L - n_cL_c - n_sL_s - \text{margin}$', '$\text{dBm}$', 'Check that enough light reaches the receiver after every loss.', '[{"symbol":"$\\alpha$","meaning":"fiber attenuation","unit":"$\\text{dB/km}$"},{"symbol":"$L$","meaning":"length","unit":"$\\text{km}$"},{"symbol":"$L_c, L_s$","meaning":"loss per connector and per splice","unit":"$\\text{dB}$"}]'::jsonb, 'Typical: 0.2–0.35 dB/km single-mode, 0.5 dB per connector, 0.1 dB per fusion splice.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'fiber optics' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE'
