SELECT gen_random_uuid()::text, 'formula', '$r = \sqrt[3]{\frac{GMT^2}{4\pi^2}} = 42{,}164\ \text{km}$', 'Geostationary Orbit', '$r = \left(\frac{GM\,T^2}{4\pi^2}\right)^{1/3} = 42{,}164\ \text{km};\quad h = 35{,}786\ \text{km};\quad t_{up+down} \approx 0.24\ \text{s}$', '$\text{km}$', 'The one orbit whose period matches the earth''s rotation, so the satellite seems to stand still.', '[{"symbol":"$GM$","meaning":"Earth''s gravitational parameter, 3.986 × 10¹⁴ m³/s²","unit":null},{"symbol":"$T$","meaning":"sidereal day, 86,164 s","unit":"$\\text{s}$"}]'::jsonb, 'A one-way hop (up and down) takes about 240 ms; a conversation''s round trip about 0.5 s.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'satellite and cellular' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
