SELECT gen_random_uuid()::text, 'formula', '$\frac{C}{N_0} = \text{EIRP} - L + \frac{G}{T} + 228.6$', 'Satellite Link Budget (C/N₀)', '$\frac{C}{N_0}(\text{dBHz}) = \text{EIRP}(\text{dBW}) - L(\text{dB}) + \frac{G}{T}(\text{dB/K}) + 228.6$', '$\text{dBHz}$', 'Carrier-to-noise density of a link; 228.6 is −10 log k.', '[{"symbol":"$\\text{EIRP}$","meaning":"effective isotropic radiated power","unit":"$\\text{dBW}$"},{"symbol":"$L$","meaning":"path and other losses","unit":"$\\text{dB}$"},{"symbol":"$G/T$","meaning":"receiver figure of merit","unit":"$\\text{dB/K}$"}]'::jsonb, 'C/N = C/N₀ − 10 log B.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'satellite and cellular' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
