SELECT gen_random_uuid()::text, 'formula', '$N = i^2 + ij + j^2,\ \frac{D}{R} = \sqrt{3N}$', 'Cellular Frequency Reuse', '$N = i^2 + ij + j^2,\qquad \frac{D}{R} = \sqrt{3N},\qquad \frac{C}{I} \approx \frac{(D/R)^n}{6}$', NULL, 'Cells reuse the same channels a cluster apart; bigger clusters mean less interference but fewer channels per cell.', '[{"symbol":"$N$","meaning":"cluster size","unit":null},{"symbol":"$D$","meaning":"distance between co-channel cells","unit":"$\\text{m}$"},{"symbol":"$R$","meaning":"cell radius","unit":"$\\text{m}$"},{"symbol":"$n$","meaning":"path-loss exponent (about 4)","unit":null}]'::jsonb, 'N = 7, n = 4 gives C/I ≈ 18.7 dB.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'satellite and cellular' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
