SELECT gen_random_uuid()::text, 'formula', '$A = \lambda h$', 'Traffic Intensity (Erlang)', '$A = \lambda\,h\quad (\text{Erlang})$', '$\text{E}$', 'Average number of calls in progress: one channel busy all the time is one erlang.', '[{"symbol":"$\\lambda$","meaning":"calls per hour","unit":null},{"symbol":"$h$","meaning":"average holding time","unit":"$\\text{h}$"}]'::jsonb, 'Keep λ and h in the same time unit; the Erlang B table then gives channels for a blocking probability.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'satellite and cellular' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
