SELECT gen_random_uuid()::text, 'formula', '$\eta = \frac{1}{1 + 2a},\ a = \frac{t_{prop}}{t_{frame}}$', 'Stop-and-Wait Efficiency', '$\eta = \frac{1}{1 + 2a},\qquad a = \frac{t_{prop}}{t_{frame}} = \frac{d/v}{L/R}$', NULL, 'Sending one frame and waiting for its acknowledgement wastes the round trip.', '[{"symbol":"$t_{prop}$","meaning":"propagation delay","unit":"$\\text{s}$"},{"symbol":"$t_{frame}$","meaning":"time to send one frame","unit":"$\\text{s}$"},{"symbol":"$L, R$","meaning":"frame length and bit rate","unit":null}]'::jsonb, 'Over long or fast links a is large: sliding windows keep the line busy.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'data communications' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
