SELECT gen_random_uuid()::text, 'formula', '$\eta = \frac{\text{data bits}}{\text{bits per character}}$', 'Asynchronous Framing Efficiency', '$\eta = \frac{n_{data}}{n_{start} + n_{data} + n_{parity} + n_{stop}}$', NULL, 'Start and stop bits around every character cost throughput.', '[{"symbol":"$n$","meaning":"bits of each kind per character","unit":null}]'::jsonb, '8N1 (1 start, 8 data, no parity, 1 stop): 80%; 9600 bit/s carries 960 characters per second.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Fundamentals of Electronic Communications' AND t."subject" = 'EE' AND s."normKey" = 'data communications' AND s."active"), NULL, true, 'PENDING', now(), now()
